import { getState, update } from './store.js';
const copy=v=>JSON.parse(JSON.stringify(v));
const now=()=>new Date().toISOString();
let serial=0;
const uid=p=>`${p}-${Date.now().toString(36)}-${(++serial).toString(36)}`;
const fail=error=>({ok:false,error});
const round=n=>Math.round(n*100)/100;
const stable=v=>JSON.stringify(v);
const human=(s,name)=>s.agents.find(a=>a.type==='human'&&(a.name===name||a.id===name));
const findProcess=(s,id)=>s.studio?.processes.find(p=>p.id===id);
const findRun=(s,id)=>s.studio?.runs.find(r=>r.id===id);
const policyApplies=(policy,team)=>!policy.scope||['Toute l’organisation',"Toute l'organisation",'Tous les agents','Tous les processus','Organization'].includes(policy.scope)||policy.scope===team;
function decisionAuthority(s,owner){
 const actor=human(s,s.workspace?.actorId||'h-matthieu');
 if(!actor)return {ok:false,error:'Sélectionnez un profil humain du registre pour décider.'};
 const assigned=human(s,owner);if(!assigned)return {ok:false,error:'Le responsable affecté est introuvable.'};
 let cursor=assigned;const seen=new Set();
 while(cursor&&!seen.has(cursor.id)){if(cursor.id===actor.id)return {ok:true,actor,assigned,override:actor.id!==assigned.id};seen.add(cursor.id);cursor=human(s,cursor.manager);}
 return {ok:false,error:`Cette intervention appartient à ${assigned.name} ou à sa hiérarchie. Changez de profil pour décider.`};
}
