function fromLegacy(p,s){
 if(p.id==='p-rfp')return rfpDesign(s);
 const stages=defaultStages();
 const nodes=p.steps.map((x,i)=>{
 const actor=s.agents.find(a=>a.name===x.actor);
 const agentId=actor?.type==='agent'?actor.id:p.agentIds[0];
 const stageIndex=Math.min(4,Math.floor(i*5/Math.max(p.steps.length,1)));
 return node(`${p.id}-step-${i+1}`,x.name,stages[stageIndex].id,agentId,p.owner,{kind:x.kind==='human'?'human':x.kind==='control'?'tool':'agent',deps:i?[`${p.id}-step-${i}`]:[],skills:actor?.skills?.slice(0,2)||['Contrôle'],action:`${p.id}.${i+1}`,estimatedMinutes:Math.max(3,20-i*3)});
 });
 return {outcome:p.description,trigger:'Lancement manuel ou événement métier (simulation)',deadlineHours:24,autonomy:'supervised',stages,nodes,edges:edgesFromNodes(nodes)};
}
function processRecord(p,s){
 const design=fromLegacy(p,s);
 return {id:p.id,name:p.name,owner:p.owner,team:p.team,leadAgentId:p.agentIds[0],status:p.status,version:p.id==='p-rfp'?6:1,published:copy(design),draft:copy(design),undo:[],redo:[],versions:[],improvements:[
 {id:'parallel',title:'Accélérer la préparation',description:'Réduire les délais des étapes de préparation dans le brouillon, à valider par un test.',impact:'Hypothèse : −20 % de temps de préparation',applied:false},
 {id:'evidence',title:'Renforcer les preuves de validation',description:'Exiger une source et un critère d’acceptation explicites pour chaque étape.',impact:'Hypothèse : moins de reprises lors de la revue',applied:false},
 {id:'staffing',title:'Comparer le meilleur agent disponible',description:'Proposer une affectation au meilleur agent qualifié pour les étapes de rédaction.',impact:'Comparer les résultats avant publication',applied:false}
 ],createdAt:now(),seedMetrics:{cases:p.cases,autonomousRate:p.autonomousRate,medianTime:p.medianTime,notice:'Indicateurs du scénario fictif'}};
}
function runRecord(p,design,{draft=false,title='',scenario='bid'}={}){
 const id=uid('wf-run');
 return {id,processId:p.id,title:title||`${p.name} · dossier ${id.slice(-4).toUpperCase()}`,version:draft?`Brouillon ${p.version+1}`:p.version,snapshot:copy(design),isTest:draft,status:'running',scenario,startedAt:now(),finishedAt:null,steps:design.nodes.map(n=>({nodeId:n.id,status:'pending',actor:'',agentId:n.agentId,minutes:0,cost:0,evidence:[],tools:[],output:'',approvals:[]})),request:null,events:[{time:now(),title:draft?'Test du brouillon lancé':'Exécution locale lancée',detail:'Simulation déterministe ; aucun effet dans un système externe.'}],metrics:{agentMinutes:0,humanMinutes:0,cost:0}};
}
function historicalRun(p,design,title,i){
 const r=runRecord(p,design,{title});r.id=`wf-history-${p.id}-${i}`;r.startedAt=`2026-10-${String(20+i).padStart(2,'0')}T09:00:00Z`;r.finishedAt=`2026-10-${String(20+i).padStart(2,'0')}T13:00:00Z`;r.status=i===0?'failed':'completed';r.historical=true;
 r.steps.forEach((st,j)=>{const n=design.nodes[j];st.status=i===0&&j>2?'pending':n.condition==='decline'?'skipped':'completed';st.actor=n.owner;st.minutes=n.estimatedMinutes;st.cost=round(n.estimatedMinutes*0.05);st.evidence=['Exemple historique fictif','Résultat accepté dans le scénario'];st.output=`${n.name} — résultat de démonstration`;st.tools=[{name:n.kind==='tool'?n.action:'read_approved_documents',status:'simulated',input:{case:title},output:'Jeu de données fictif'}];});
 r.events=[{time:r.startedAt,title:'Exemple historique',detail:'Ces événements appartiennent au scénario de démonstration.'},{time:r.finishedAt,title:i===0?'Source manquante dans le scénario':'Dossier fictif terminé',detail:i===0?'La simulation historique illustre un échec de collecte.':'Toutes les étapes applicables ont été acceptées.'}];
 r.metrics={agentMinutes:156+i*12,humanMinutes:18+i*2,cost:round(7.4+i*0.6)};return r;
}
export function initStudio(){
 const s=getState();
 if(s.studio?.version===1&&Array.isArray(s.studio.processes)&&Array.isArray(s.studio.runs)&&Array.isArray(s.studio.grants)){const missing=s.processes.filter(p=>!s.studio.processes.some(x=>x.id===p.id));if(missing.length)update(st=>missing.forEach(p=>st.studio.processes.push(processRecord(p,st))),'Processus ajoutés au studio',`${missing.length} processus existants repris sans écraser les brouillons`);return {ok:true,initialized:false,added:missing.length};}
 update(st=>{
 st.studio={version:1,processes:st.processes.map(p=>processRecord(p,st)),runs:[],grants:[]};
 const p=st.studio.processes.find(p=>p.id==='p-rfp');
 if(p){['Meridian · reporting institutionnel','Horizon · mandat européen','Atlas Partners · due diligence','Solstice · gestion déléguée','Northwind · sélection de fonds','Helios · offre de services'].forEach((title,i)=>st.studio.runs.push(historicalRun(p,p.published,title,i)));
 const waiting=runRecord(p,p.published,{title:'Horizon · appel d’offres institutionnel'});st.studio.runs.unshift(waiting);advanceInternal(st,waiting);
 }
 },'Studio de processus initialisé','Version 1 · données et exécutions locales fictives');
 return {ok:true,initialized:true};
}
export function validateDraft(d){
 const errors=[];const order=[];
 if(!d||!Array.isArray(d.stages)||!Array.isArray(d.nodes)||!Array.isArray(d.edges))return {ok:false,errors:['Structure du processus invalide.'],order};
 if(!String(d.outcome||'').trim())errors.push('Le résultat attendu est requis.');if(!['supervised','approval','observe'].includes(d.autonomy))errors.push('Choisissez un mode d’autonomie valide.');
 if(!d.stages.length)errors.push('Conservez au moins une étape de phase.');
 if(!d.nodes.length)errors.push('Conservez au moins une tâche.');
 const stageIds=d.stages.map(x=>x.id),nodeIds=d.nodes.map(x=>x.id);const stages=new Set(stageIds),nodes=new Set(nodeIds);
 if(stages.size!==stageIds.length||nodes.size!==nodeIds.length)errors.push('Les identifiants doivent être uniques.');
 for(const st of d.stages){if(!String(st.name||'').trim())errors.push('Chaque phase doit avoir un nom.');if(!Number.isFinite(Number(st.deadlineHours))||Number(st.deadlineHours)<0)errors.push('Le délai de phase doit être positif ou nul.');}
 for(const n of d.nodes){if(!String(n.name||'').trim())errors.push('Chaque tâche doit avoir un nom.');if(!stages.has(n.stageId))errors.push(`Phase introuvable pour ${n.name}.`);if(!['agent','human','tool'].includes(n.kind))errors.push(`Type de tâche invalide : ${n.name}.`);if(!['never','ask','allow'].includes(n.external))errors.push(`Autorité externe invalide : ${n.name}.`);if(!Number.isFinite(Number(n.confidence))||n.confidence<0||n.confidence>1)errors.push(`Seuil de confiance invalide : ${n.name}.`);if(!Number.isFinite(Number(n.spendLimit))||n.spendLimit<0)errors.push(`Budget invalide : ${n.name}.`);if(!String(n.action||'').trim())errors.push(`Action requise : ${n.name}.`);if(!Number.isFinite(Number(n.estimatedMinutes))||Number(n.estimatedMinutes)<=0)errors.push(`Durée estimée invalide : ${n.name}.`);if(!['best','fixed','shadow'].includes(n.staffing))errors.push(`Affectation invalide : ${n.name}.`);if(!['own','shared','catalog'].includes(n.source))errors.push(`Périmètre de recherche invalide : ${n.name}.`);if(n.staffing==='shadow'&&n.challengerId&&n.challengerId===n.agentId)errors.push(`Le challenger doit être différent de l’agent affecté : ${n.name}.`);if(!Array.isArray(n.inputs)||!Array.isArray(n.outputs)||!Array.isArray(n.skills)||!Array.isArray(n.deps))errors.push(`Contrat de données invalide : ${n.name}.`);if(n.kind==='human'&&!n.owner)errors.push(`Responsable humain requis : ${n.name}.`);if(n.kind!=='human'&&!n.agentId&&n.staffing!=='best')errors.push(`Agent requis : ${n.name}.`);}
 const seenEdges=new Set();const indegree=Object.fromEntries(nodeIds.map(id=>[id,0]));const adjacency=Object.fromEntries(nodeIds.map(id=>[id,[]]));
 for(const e of d.edges){if(!nodes.has(e.from)||!nodes.has(e.to)){errors.push('Une dépendance référence une tâche absente.');continue;}if(e.from===e.to){errors.push('Une tâche ne peut pas dépendre d’elle-même.');continue;}const key=`${e.from}:${e.to}`;if(seenEdges.has(key)){errors.push('Une dépendance est dupliquée.');continue;}seenEdges.add(key);const source=d.nodes.find(n=>n.id===e.from),target=d.nodes.find(n=>n.id===e.to);if(stageIds.indexOf(source.stageId)>stageIds.indexOf(target.stageId))errors.push('Une dépendance ne peut pas revenir vers une phase précédente.');indegree[e.to]++;adjacency[e.from].push(e.to);}
 for(const n of d.nodes){const deps=[...(n.deps||[])].sort();const edges=d.edges.filter(e=>e.to===n.id).map(e=>e.from).sort();if(stable(deps)!==stable(edges))errors.push(`Dépendances incohérentes pour ${n.name}.`);}
 const queue=d.nodes.filter(n=>indegree[n.id]===0).map(n=>n.id);
 while(queue.length){const current=queue.shift();order.push(current);for(const next of adjacency[current]||[]){if(--indegree[next]===0)queue.push(next);}}
 if(order.length!==d.nodes.length)errors.push('Le processus contient une boucle de dépendances.');
 if(!Number.isFinite(Number(d.deadlineHours))||Number(d.deadlineHours)<=0)errors.push('Le délai global doit être strictement positif.');
 return {ok:errors.length===0,errors:[...new Set(errors)],order};
}
function currentProcess(id){initStudio();return findProcess(getState(),id);}
export function editDraft(id,fn,label='Brouillon modifié'){
 const p=currentProcess(id);if(!p)return fail('Processus introuvable.');
 const next=copy(p.draft);try{fn(next);}catch(error){return fail(error.message||'Modification invalide.');}
 const check=validateDraft(next);if(!check.ok)return fail(check.errors.join(' '));
 if(stable(next)===stable(p.draft))return {ok:true,changed:false};
 update(s=>{const x=findProcess(s,id);x.undo=[...x.undo,copy(x.draft)].slice(-40);x.redo=[];x.draft=next;},label,p.name);
 return {ok:true,changed:true};
}
export function undoDraft(id){const p=currentProcess(id);if(!p?.undo.length)return fail('Aucune modification à annuler.');update(s=>{const x=findProcess(s,id);x.redo.push(copy(x.draft));x.draft=x.undo.pop();},'Modification annulée',p.name);return {ok:true};}
export function redoDraft(id){const p=currentProcess(id);if(!p?.redo.length)return fail('Aucune modification à rétablir.');update(s=>{const x=findProcess(s,id);x.undo.push(copy(x.draft));x.draft=x.redo.pop();},'Modification rétablie',p.name);return {ok:true};}
export function discardDraft(id){const p=currentProcess(id);if(!p)return fail('Processus introuvable.');if(!p.published)return fail('Ce processus n’a pas encore de version publiée.');update(s=>{const x=findProcess(s,id);x.draft=copy(x.published);x.undo=[];x.redo=[];x.improvements.forEach(i=>i.applied=false);},'Brouillon écarté',p.name);return {ok:true};}
export function diffDraft(id){const p=currentProcess(id);if(!p)return [];const before=p.published||{nodes:[],stages:[],edges:[]};const after=p.draft;const changes=[];for(const field of ['outcome','trigger','deadlineHours','autonomy'])if(stable(before[field])!==stable(after[field]))changes.push({label:({outcome:'Résultat attendu',trigger:'Déclenchement',deadlineHours:'Délai global',autonomy:'Autonomie'})[field],before:before[field]??'—',after:after[field]});for(const n of after.nodes){const old=before.nodes.find(x=>x.id===n.id);if(!old)changes.push({label:'Tâche ajoutée',before:'—',after:n.name});else if(stable(old)!==stable(n))changes.push({label:`Tâche modifiée · ${n.name}`,before:old.name,after:n.name});}for(const n of before.nodes)if(!after.nodes.some(x=>x.id===n.id))changes.push({label:'Tâche retirée',before:n.name,after:'—'});if(stable(before.stages)!==stable(after.stages))changes.push({label:'Phases et délais',before:before.stages.map(x=>x.name).join(' → '),after:after.stages.map(x=>x.name).join(' → ')});if(stable(before.edges)!==stable(after.edges))changes.push({label:'Dépendances',before:`${before.edges.length} liens`,after:`${after.edges.length} liens`});return changes;}
export function publishDraft(id){const p=currentProcess(id);if(!p)return fail('Processus introuvable.');const check=validateDraft(p.draft);if(!check.ok)return fail(check.errors.join(' '));if(p.published&&!diffDraft(id).length)return fail('Le brouillon ne contient aucune modification.');const version=p.version+1;update(s=>{const x=findProcess(s,id);if(x.published)x.versions.push({version:x.version,snapshot:copy(x.published),publishedAt:x.publishedAt||x.createdAt});x.published=copy(x.draft);x.version=version;x.publishedAt=now();x.undo=[];x.redo=[];if(x.status==='draft')x.status='live';syncLegacy(s,x);},'Version de processus publiée',`${p.name} · version ${version} · nouvelles exécutions uniquement`);return {ok:true,version};}
function syncLegacy(s,p){let x=s.processes.find(x=>x.id===p.id);const d=p.published||p.draft;const value={id:p.id,name:p.name,description:d.outcome,owner:p.owner,team:p.team,agentIds:[...new Set(d.nodes.map(n=>n.agentId).filter(id=>s.agents.some(a=>a.id===id&&a.type==='agent')))],goalId:p.goalId||x?.goalId||s.goals[0]?.id,status:p.status,cases:x?.cases||0,autonomousRate:x?.autonomousRate||0,medianTime:x?.medianTime||'—',steps:d.nodes.map(n=>({name:n.name,actor:n.kind==='human'?n.owner:s.agents.find(a=>a.id===n.agentId)?.name||'Agent à affecter',kind:n.kind==='human'?'human':n.kind==='tool'?'control':'agent'}))};if(x)Object.assign(x,value);else s.processes.push(value);for(const goal of s.goals){goal.processIds=(goal.processIds||[]).filter(pid=>pid!==p.id);if(goal.id===value.goalId)goal.processIds.push(p.id);}}
export function patchStep(id,nodeId,patch){return editDraft(id,d=>{const n=d.nodes.find(n=>n.id===nodeId);if(!n)throw Error('Tâche introuvable.');const allowed=['name','stageId','kind','agentId','owner','outcome','evidence','skills','staffing','source','challengerId','spendLimit','external','confidence','inputs','outputs','deps','action','estimatedMinutes','condition'];for(const key of allowed)if(Object.hasOwn(patch,key))n[key]=copy(patch[key]);n.spendLimit=Number(n.spendLimit);n.confidence=Number(n.confidence);n.estimatedMinutes=Number(n.estimatedMinutes)||1;if(patch.deps)n.deps=[...new Set(patch.deps)];const shadowError=checkShadow(getState(),n);if(shadowError)throw Error(shadowError);d.edges=edgesFromNodes(d.nodes,d.edges);},'Tâche modifiée');}
export function addStep(id,patch={}){const p=currentProcess(id);if(!p)return fail('Processus introuvable.');const nodeId=uid('step');const result=editDraft(id,d=>{const stageId=patch.stageId||d.stages.at(-1).id;d.nodes.push(node(nodeId,patch.name||'Nouvelle tâche',stageId,patch.agentId||p.leadAgentId,patch.owner||p.owner,{...patch,id:nodeId}));d.edges=edgesFromNodes(d.nodes,d.edges);},'Tâche ajoutée');return {...result,nodeId};}
export function duplicateStep(id,nodeId){const p=currentProcess(id);const old=p?.draft.nodes.find(n=>n.id===nodeId);if(!old)return fail('Tâche introuvable.');return addStep(id,{...copy(old),name:`${old.name} · copie`});}
export function removeStep(id,nodeId){return editDraft(id,d=>{if(d.nodes.length<=1)throw Error('La dernière tâche ne peut pas être retirée.');if(!d.nodes.some(n=>n.id===nodeId))throw Error('Tâche introuvable.');d.nodes=d.nodes.filter(n=>n.id!==nodeId);d.nodes.forEach(n=>n.deps=(n.deps||[]).filter(dep=>dep!==nodeId));d.edges=edgesFromNodes(d.nodes,d.edges);},'Tâche retirée et dépendances nettoyées');}
export function patchStage(id,stageId,patch){return editDraft(id,d=>{const st=d.stages.find(st=>st.id===stageId);if(!st)throw Error('Phase introuvable.');if(patch.name!==undefined)st.name=String(patch.name).trim();if(patch.deadlineHours!==undefined)st.deadlineHours=Number(patch.deadlineHours);if(patch.index!==undefined){const index=Math.max(0,Math.min(d.stages.length-1,Number(patch.index)));d.stages=d.stages.filter(x=>x.id!==stageId);d.stages.splice(index,0,st);}},'Phase modifiée');}
export function addStage(id,patch={}){const stageId=uid('stage');const result=editDraft(id,d=>{d.stages.push(stage(stageId,patch.name||'Nouvelle phase',Number(patch.deadlineHours??4)));},'Phase ajoutée');return {...result,stageId};}
export function removeStage(id,stageId){return editDraft(id,d=>{if(d.stages.length<=1)throw Error('Conservez au moins une phase.');const index=d.stages.findIndex(x=>x.id===stageId);if(index<0)throw Error('Phase introuvable.');if(d.nodes.some(n=>n.stageId===stageId))throw Error('Déplacez les tâches de cette phase avant de la retirer.');d.stages.splice(index,1);},'Phase retirée');}
export function setEdges(id,edges){return editDraft(id,d=>{d.edges=copy(edges);d.nodes.forEach(n=>n.deps=d.edges.filter(e=>e.to===n.id).map(e=>e.from));},'Dépendances mises à jour');}
export function updateSetup(id,patch){const p=currentProcess(id);if(!p)return fail('Processus introuvable.');const s=getState();if(patch.owner&&!human(s,patch.owner))return fail('Choisissez un responsable humain du registre.');if(patch.leadAgentId&&!s.agents.some(a=>a.id===patch.leadAgentId&&a.type==='agent'))return fail('Agent responsable introuvable.');if(patch.status&&!['live','draft','paused'].includes(patch.status))return fail('Statut invalide.');if(patch.status==='live'&&!p.published)return fail('Publiez une version avant la mise en service.');const draft=copy(p.draft);for(const k of ['outcome','trigger','deadlineHours','autonomy'])if(patch[k]!==undefined)draft[k]=patch[k];draft.deadlineHours=Number(draft.deadlineHours);const check=validateDraft(draft);if(!check.ok)return fail(check.errors.join(' '));update(st=>{const x=findProcess(st,id);for(const k of ['name','owner','team','leadAgentId','status','goalId'])if(patch[k]!==undefined)x[k]=String(patch[k]);if(stable(x.draft)!==stable(draft)){x.undo.push(copy(x.draft));x.redo=[];x.draft=draft;}syncLegacy(st,x);},'Paramètres du processus modifiés',p.name);return {ok:true};}
export function createProcess(outcome,template='rfp'){initStudio();if(typeof outcome!=='string'||outcome.trim().length<8)return fail('Décrivez un résultat attendu en au moins huit caractères.');const s=getState();const t=templates.find(t=>t.id===template)||templates[0];const processId=uid('process');const base=s.processes.find(p=>p.id===({rfp:'p-rfp',reconcile:'p-reconcile',reporting:'p-reporting',onboarding:'p-reporting',support:'p-reconcile'})[t.id])||s.processes[0];const p=processRecord({...base,id:processId,name:t.title,status:'draft'},s);p.version=0;p.published=null;p.draft=t.id==='rfp'?rfpDesign(s):fromLegacy(base,s);p.draft.outcome=outcome.trim();p.name=outcome.trim().split(/[.!?]/)[0].slice(0,72);p.createdAt=now();p.goalId=base.goalId;update(st=>{st.studio.processes.push(p);syncLegacy(st,p);},'Brouillon créé depuis un résultat',`${p.name} · modèle déterministe ${t.title}`);return {ok:true,processId};}
export function getFitCandidates(s,n){
 const wanted=(n.skills||[]).map(x=>x.toLowerCase());
 const ownTeam=s.agents.find(a=>a.id===n.agentId)?.team||human(s,n.owner)?.team||s.agents.find(a=>a.id==='h-matthieu')?.team;
 const actual=s.agents.filter(a=>a.type==='agent').map(a=>{const hits=wanted.filter(w=>(a.skills||[]).some(sk=>sk.toLowerCase().includes(w)||w.includes(sk.toLowerCase()))).length;const fit=round(Math.min(.98,.58+(wanted.length?hits/wanted.length:.5)*.28+(Number(a.quality)||0)*.001));const source=a.team===ownTeam?'own':'shared';const stage=s.capabilities?.profiles?.[a.id]?.stage;return {id:a.id,name:a.name,source,withinScope:source===(n.source||'own'),fit,verified:a.status==='active'&&!['qualification','testing'].includes(stage),type:'agent',reason:`${hits}/${wanted.length||1} compétences correspondantes · qualité illustrative ${a.quality}% · ${a.team} · ${a.status==='paused'?'suspendu':a.status==='pilot'?'en pilote':stage==='qualification'||stage==='testing'?'qualification à terminer':'en service'}`};});
 const catalog=[{id:'catalog-rfp',name:'RFP Specialist',source:'catalog',withinScope:n.source==='catalog',fit:.95,verified:false,type:'agent',reason:'Profil de catalogue fictif. Qualification et responsable requis avant affectation.'},{id:'catalog-security',name:'Security Analyst',source:'catalog',withinScope:n.source==='catalog',fit:.92,verified:false,type:'agent',reason:'Profil proposé. Les scores sont des exemples, sans exécution mesurée.'}];
 return [...actual,...catalog].sort((a,b)=>b.fit-a.fit);
}
function actorFor(s,n){if(n.kind==='human')return human(s,n.owner);if(n.staffing==='best'){const candidate=getFitCandidates(s,n).find(c=>c.withinScope&&c.verified&&s.agents.find(a=>a.id===c.id)?.status==='active');return s.agents.find(a=>a.id===candidate?.id);}return s.agents.find(a=>a.id===n.agentId);}
function checkShadow(s,n){if(n.staffing!=='shadow'||!n.challengerId)return '';if(n.challengerId===n.agentId)return 'Le challenger doit être différent de l’agent affecté.';const challenger=s.agents.find(a=>a.id===n.challengerId&&a.type==='agent');if(!challenger)return 'Le challenger doit être un agent connu du registre.';const stage=s.capabilities?.profiles?.[challenger.id]?.stage;if(challenger.status!=='active'||['qualification','testing'].includes(stage))return 'Le challenger doit être actif et sa qualification terminée.';return '';}
function mandateSignature(s,agentId){const a=s.agents.find(a=>a.id===agentId);return stable({id:a?.id,mandate:a?.mandate,autonomy:a?.autonomy});}
function actionSignature(n){return stable({id:n.id,action:n.action,kind:n.kind,inputs:n.inputs,outputs:n.outputs,spendLimit:n.spendLimit,external:n.external,confidence:n.confidence,outcome:n.outcome,owner:n.owner});}
function policySignature(s){return stable(s.policies.filter(p=>p.enabled).map(p=>({id:p.id,mode:p.mode,check:p.check,scope:p.scope,rule:p.rule})));}
function checkActor(s,n,actor){if(n.kind==='human')return actor?.type==='human'?'':'Un responsable humain du registre est requis.';if(!actor||actor.type!=='agent')return n.source==='catalog'?'Les profils du catalogue doivent être recrutés et qualifiés avant exécution.':'Aucun agent qualifié ne correspond au périmètre d’affectation. Choisissez un profil fixe ou un autre périmètre.';const profileStage=s.capabilities?.profiles?.[actor.id]?.stage;if(['qualification','testing'].includes(profileStage))return `${actor.name} doit terminer sa qualification avant exécution.`;const shadowError=checkShadow(s,n);if(shadowError)return shadowError;if(actor.status==='paused')return `${actor.name} est suspendu.`;if(Number(actor.autonomy)===0)return `${actor.name} est en observation seule.`;if(actor.mandate?.expires&&new Date(actor.mandate.expires+'T23:59:59Z')<new Date())return `Le mandat de ${actor.name} est expiré.`;if(!human(s,actor.manager))return `${actor.name} n’a pas de responsable humain valide.`;
 const requiredApps=s.capabilities?.profiles?.[actor.id]?.requiredApps||[];const connections=s.capabilities?.connections||[];for(const id of requiredApps){const connection=connections.find(c=>c.id===id);if(!connection||connection.status!=='connected'||!connection.reviewed||connection.testedRevision!==connection.revision)return `L’intégration ${connection?.name||id} requise par ${actor.name} n’est pas connectée et validée.`;}
 const policies=s.policies.filter(p=>p.enabled&&policyApplies(p,actor.team));const approved=['Documents internes','Référentiel fonds','Données marché','CRM','Comptabilité','Messagerie interne','Contrôles conformité'];
 if(policies.some(p=>p.check==='approved-tools'&&p.mode==='block')&&(actor.mandate?.tools||[]).some(t=>!approved.includes(t)))return `Un outil du mandat de ${actor.name} n’est pas approuvé par l’organisation.`;
 const baseSpend=s.agents.filter(a=>a.type==='agent').reduce((sum,a)=>sum+Number(a.cost||0),0);const studioSpend=(s.studio?.runs||[]).filter(r=>!r.historical&&!r.isTest).reduce((sum,r)=>sum+Number(r.metrics.cost||0),0);
 if(policies.some(p=>p.check==='budget'&&p.mode==='block')&&baseSpend+studioSpend+Number(n.estimatedMinutes)*.05>Number(s.settings.budget))return 'Le budget de l’organisation ne permet pas cette étape simulée.';
 return '';}
function gate(s,p,r,n,actor){if(n.kind==='human')return {reason:'Cette étape est explicitement confiée à un humain.',eligibleForAlways:false};if(n.action.startsWith('external.')&&n.external==='never')return {blocked:'Le mandat de cette tâche interdit toute action externe.'};const externalPolicies=s.policies.filter(pol=>pol.enabled&&pol.check==='external-approval'&&n.action.startsWith('external.')&&(policyApplies(pol,p.team)||policyApplies(pol,actor?.team)));if(externalPolicies.some(pol=>pol.mode==='block'))return {blocked:'La règle de l’organisation bloque cette action externe.'};const policyAsk=externalPolicies.some(pol=>pol.mode==='ask');if(policyAsk)return {reason:'La règle de l’organisation impose une validation avant engagement externe.',eligibleForAlways:false};const measuredConfidence=Math.min(.98,(Number(actor?.quality)||80)/100);if(measuredConfidence<Number(n.confidence))return {reason:`Le score illustratif ${Math.round(measuredConfidence*100)} % est sous le seuil demandé ${Math.round(n.confidence*100)} %.`,eligibleForAlways:false};if(r.snapshot.autonomy==='approval'||actor?.autonomy===1||actor?.status==='pilot')return {reason:'Le niveau de délégation exige une revue humaine pour cette action.',eligibleForAlways:false};if(n.external==='ask'&&n.action.startsWith('external.'))return {reason:'Une autorisation est requise pour cette action externe précise.',eligibleForAlways:true};if(Number(n.spendLimit)<Number(n.estimatedMinutes)*.05)return {reason:'Le coût simulé dépasse le plafond de cette étape.',eligibleForAlways:false};return null;}
function grantMatches(s,r,n,actor){return s.studio.grants.some(g=>g.processId===r.processId&&g.nodeId===n.id&&g.agentId===actor.id&&g.action===n.action&&g.actionFingerprint===actionSignature(n)&&g.mandateFingerprint===mandateSignature(s,actor.id)&&g.policyFingerprint===policySignature(s)&&Boolean(g.isTest)===Boolean(r.isTest)&&!g.revoked);}
function finishStep(s,r,n,step,actor,approved=false){step.status='completed';step.actor=actor?.name||n.owner;step.agentId=actor?.type==='agent'?actor.id:n.agentId;step.minutes=Number(n.estimatedMinutes)||1;step.cost=n.kind==='human'?0:round(step.minutes*.05);step.evidence=[n.evidence||'Critère de vérification renseigné.',`Résultat fictif : ${n.outcome}`,approved?'Validation humaine enregistrée.':'Limites du scénario vérifiées.'];step.tools=n.kind==='human'?[]:[{name:n.kind==='tool'?n.action:'read_approved_documents',status:'simulated',input:{case:r.title,inputs:n.inputs},output:'Contenu de démonstration uniquement.'}];step.output=(n.outputs||[]).join(', ')||`${n.name} — résultat accepté`;
 if(n.staffing==='shadow'&&n.challengerId&&n.kind!=='human'){
 const challenger=s.agents.find(a=>a.id===n.challengerId);const candidates=getFitCandidates(s,n);const primaryFit=candidates.find(c=>c.id===actor?.id)?.fit||0;const challengerFit=candidates.find(c=>c.id===challenger?.id)?.fit||0;
 step.shadowComparison={mode:'deterministic-simulation',primaryAgentId:actor?.id,challengerId:challenger?.id,primaryFit,challengerFit,primaryQuality:Number(actor?.quality)||0,challengerQuality:Number(challenger?.quality)||0,actionExecutedBy:actor?.id,challengerActions:0,result:challengerFit>primaryFit?'Le challenger a une meilleure correspondance de compétences dans ce scénario.':'Le profil affecté reste le meilleur correspondant dans ce scénario.'};
 step.evidence.push(`Comparaison fictive sans exécution du challenger : ${actor?.name} ${Math.round(primaryFit*100)} % d’adéquation / ${challenger?.name} ${Math.round(challengerFit*100)} %. ${step.shadowComparison.result}`);
 step.output+=` · Challenger ${challenger?.name} évalué en observation uniquement.`;
 }
 step.finishedAt=now();r.metrics[n.kind==='human'?'humanMinutes':'agentMinutes']+=step.minutes;r.metrics.cost=round(r.metrics.cost+step.cost);r.events.push({time:now(),title:n.name,detail:`${step.actor} · ${approved?'validé':'simulé'} · ${step.minutes} min`});}
function failRun(r,n,error){r.status='failed';r.finishedAt=now();r.request=null;const st=r.steps.find(x=>x.nodeId===n?.id);if(st){st.status='failed';st.error=error;}r.events.push({time:now(),title:'Exécution arrêtée',detail:error});}
function advanceInternal(s,r){const p=findProcess(s,r.processId);if(!p||r.status==='completed'||r.status==='failed'||r.request)return;const check=validateDraft(r.snapshot);if(!check.ok){failRun(r,null,check.errors.join(' '));return;}r.status='running';for(const nodeId of check.order){const n=r.snapshot.nodes.find(n=>n.id===nodeId);const step=r.steps.find(x=>x.nodeId===nodeId);if(step.status==='completed'||step.status==='skipped')continue;if(n.condition&&n.condition!==r.scenario){step.status='skipped';step.output='Branche non retenue dans ce scénario.';continue;}if(n.deps.some(dep=>!['completed','skipped'].includes(r.steps.find(x=>x.nodeId===dep)?.status)))continue;const actor=actorFor(s,n);const error=checkActor(s,n,actor);if(error){failRun(r,n,error);return;}const g=gate(s,p,r,n,actor);if(g?.blocked){failRun(r,n,g.blocked);return;}const granted=g?.eligibleForAlways&&grantMatches(s,r,n,actor);if(g&&!granted){step.status='waiting';step.actor=actor?.name||n.owner;step.agentId=actor?.type==='agent'?actor.id:n.agentId;const requestId=uid('approval');const fingerprint=actionSignature(n);r.request={id:requestId,token:uid('approval-token'),nodeId:n.id,title:n.kind==='human'?n.name:`Autoriser : ${n.name}`,owner:human(s,n.owner)?.name||p.owner,agentId:step.agentId,action:n.action,reason:g.reason,eligibleForAlways:g.eligibleForAlways,scope:`${p.name} / ${actor?.name||n.owner} / ${n.action}`,amount:round(n.estimatedMinutes*.05),createdAt:now(),actionFingerprint:fingerprint,mandateFingerprint:mandateSignature(s,step.agentId),policyFingerprint:policySignature(s)};r.status='waiting';r.events.push({time:now(),title:'Intervention attendue',detail:`${r.request.owner} · ${r.request.title}`});return;}finishStep(s,r,n,step,actor);}
 if(r.steps.every(st=>['completed','skipped'].includes(st.status))){r.status='completed';r.finishedAt=now();r.events.push({time:now(),title:'Dossier terminé',detail:'Toutes les étapes applicables sont acceptées. Aucun effet externe réel.'});}
}
export function startRun(processId,{draft=false,title='',scenario='bid'}={}){const p=currentProcess(processId);if(!p)return fail('Processus introuvable.');if(!draft&&p.status!=='live')return fail('Le processus doit être en service pour démarrer un dossier.');const design=draft?p.draft:p.published;if(!design)return fail('Publiez une version avant de lancer un dossier.');if(!draft&&design.autonomy==='observe')return fail('Ce processus est en observation. Lancez un test explicite du brouillon ou publiez un mode d’exécution.');const valid=validateDraft(design);if(!valid.ok)return fail(valid.errors.join(' '));const s=getState();for(const n of design.nodes){if(n.condition&&n.condition!==scenario)continue;const error=checkActor(s,n,actorFor(s,n));if(error)return fail(error);}const r=runRecord(p,design,{draft,title,scenario});update(st=>{st.studio.runs.unshift(r);advanceInternal(st,r);},draft?'Test de brouillon lancé':'Exécution de processus lancée',`${p.name} · version ${r.version} · données simulées`);return {ok:true,runId:r.id};}
export function advanceRun(runId){initStudio();const r=findRun(getState(),runId);if(!r)return fail('Exécution introuvable.');if(r.request)return fail('Une décision humaine est attendue.');if(['completed','failed'].includes(r.status))return fail('Cette exécution est terminée.');update(s=>advanceInternal(s,findRun(s,runId)),'Exécution poursuivie',r.title);return {ok:true};}
export function resolveApproval(runId,{requestId,token,outcome='once',comment=''}={}){initStudio();const s=getState(),r=findRun(s,runId);if(!r||r.status!=='waiting'||!r.request)return fail('Aucune demande active pour cette exécution.');const q=r.request;const authority=decisionAuthority(s,q.owner);if(!authority.ok)return fail(authority.error);if(q.id!==requestId||q.token!==token)return fail('Cette demande a changé ou a déjà été traitée. Rechargez la décision.');if(!['once','always','deny'].includes(outcome))return fail('Issue de décision invalide.');const n=r.snapshot.nodes.find(n=>n.id===q.nodeId);if(!n)return fail('Tâche de décision introuvable.');if(outcome!=='deny'){if(q.actionFingerprint!==actionSignature(n)||q.mandateFingerprint!==mandateSignature(s,q.agentId)||q.policyFingerprint!==policySignature(s))return fail('Le mandat, la règle ou l’action a changé. Refusez la demande et relancez un dossier actualisé.');const actor=n.kind==='human'?human(s,q.owner):s.agents.find(a=>a.id===q.agentId);const error=checkActor(s,n,actor);if(error)return fail(error);if(!human(s,q.owner))return fail('Le responsable de décision n’est plus dans le registre.');if(outcome==='always'&&!q.eligibleForAlways)return fail('Cette validation ne peut pas devenir une autorisation permanente.');}
 update(st=>{const run=findRun(st,runId);const request=copy(run.request);const task=run.snapshot.nodes.find(n=>n.id===request.nodeId);const step=run.steps.find(x=>x.nodeId===task.id);step.approvals.push({requestId:request.id,outcome,owner:request.owner,decidedBy:authority.actor.name,decidedById:authority.actor.id,override:authority.override,comment:String(comment).trim(),time:now()});run.request=null;if(outcome==='deny'){step.status='failed';failRun(run,task,`Refusé par ${authority.actor.name}${authority.override?' au titre de la responsabilité hiérarchique de '+request.owner:''}${comment?' : '+comment:''}`);return;}if(outcome==='always'){st.studio.grants.push({id:uid('grant'),processId:run.processId,nodeId:task.id,agentId:request.agentId,action:task.action,actionFingerprint:request.actionFingerprint,mandateFingerprint:request.mandateFingerprint,policyFingerprint:request.policyFingerprint,isTest:run.isTest,owner:request.owner,approvedBy:authority.actor.id,createdAt:now(),revoked:false});}run.events.push({time:now(),title:outcome==='always'?'Autorisation limitée enregistrée':'Autorisé une fois',detail:`${authority.actor.name}${authority.override?' · arbitrage hiérarchique pour '+request.owner:''} · ${comment||request.title}`});finishStep(st,run,task,step,task.kind==='human'?human(st,request.owner):st.agents.find(a=>a.id===request.agentId),true);run.status='running';advanceInternal(st,run);},outcome==='deny'?'Intervention refusée':outcome==='always'?'Autorisation de processus enregistrée':'Intervention approuvée',`${r.title} · ${q.title}${authority.override?' · arbitrage hiérarchique : '+authority.actor.name+' pour '+q.owner:''}`,{actorId:authority.actor.id});return {ok:true,status:findRun(getState(),runId).status};}
export function reassignApproval(runId,owner){initStudio();const s=getState(),r=findRun(s,runId);if(!r?.request||r.status!=='waiting')return fail('Aucune décision à réaffecter.');const authority=decisionAuthority(s,r.request.owner);if(!authority.ok)return fail(authority.error);const target=human(s,owner);if(!target)return fail('Sélectionnez un humain du registre.');update(st=>{const run=findRun(st,runId);run.request.owner=target.name;run.request.token=uid('approval-token');run.events.push({time:now(),title:'Intervention réaffectée',detail:`Nouveau responsable : ${target.name}`});},'Intervention réaffectée',`${r.title} → ${target.name}${authority.override?' · arbitrage hiérarchique par '+authority.actor.name:''}`,{actorId:authority.actor.id});return {ok:true};}
export function cancelRun(runId){initStudio();const r=findRun(getState(),runId);if(!r||['failed','completed'].includes(r.status))return fail('Cette exécution est déjà terminée.');update(s=>failRun(findRun(s,runId),null,'Exécution interrompue par le responsable du scénario.'),'Exécution interrompue',r.title);return {ok:true};}
export function naturalChange(id,text){if(!currentProcess(id))return fail('Processus introuvable.');const request=String(text||'').trim();if(request.length<5)return fail('Décrivez la modification souhaitée.');const q=request.toLowerCase();let explanation='';let result;
 if(/(valid|humain|revue|approb)/.test(q)){
 const process=currentProcess(id);const beforeSubmission=/avant/.test(q)&&/(remise|envoi|soumission|soumettre|envoyer)/.test(q);
 if(beforeSubmission){const target=process.draft.nodes.find(n=>n.action==='external.submit-rfp'||n.action.startsWith('external.submit')||/(soumettre|soumission|envoyer|envoi|remise)/i.test(n.name));if(!target)return fail('Aucune étape de remise ou d’envoi n’est identifiable. Sélectionnez l’étape cible dans le canevas et ajoutez une dépendance.');const nodeId=uid('human-review');result=editDraft(id,d=>{const targetNode=d.nodes.find(n=>n.id===target.id);const prior=[...targetNode.deps];const review=node(nodeId,'Valider avant la remise',targetNode.stageId,targetNode.agentId,targetNode.owner||process.owner,{kind:'human',deps:prior,condition:targetNode.condition||'',action:'human.review-before-submission',outcome:'Valider le dossier exact avant toute remise.',estimatedMinutes:10});d.nodes.splice(d.nodes.findIndex(n=>n.id===target.id),0,review);targetNode.deps=[nodeId];d.edges=edgesFromNodes(d.nodes,d.edges);},'Validation insérée avant remise');explanation=`Une validation humaine est insérée avant « ${target.name} » ; les dépendances d’origine sont conservées.`;}
 else{result=addStep(id,{name:'Validation humaine complémentaire',kind:'human',deps:process.draft.nodes.filter(n=>n.stageId===process.draft.stages.at(-1).id).map(n=>n.id)});explanation='Une validation humaine a été ajoutée en fin de processus.';}
 }
 else if(/(délai|delai|heure|jour|rapide)/.test(q)){const match=q.match(/(\d+)\s*(h|heure|j|jour)/);const hours=match?Number(match[1])*(match[2].startsWith('j')?24:1):Math.max(1,Math.round(currentProcess(id).draft.deadlineHours*.8));result=editDraft(id,d=>d.deadlineHours=hours,'Délai proposé en langage naturel');explanation=`Le délai global du brouillon est fixé à ${hours} heures.`;}
 else if(/(source|preuve|qualité|qualite)/.test(q)){result=editDraft(id,d=>d.nodes.forEach(n=>{n.evidence='Source identifiable, extrait de preuve et critère d’acceptation documentés.';n.confidence=Math.max(n.confidence,.9);}), 'Contrôles renforcés');explanation='Les preuves attendues et le seuil de revue sont renforcés.';}
 else if(/(budget|coût|cout|euro|€)/.test(q)){const amount=Number(q.match(/\d+(?:[.,]\d+)?/)?.[0]?.replace(',','.'))||25;result=editDraft(id,d=>d.nodes.forEach(n=>n.spendLimit=amount),'Plafonds du brouillon modifiés');explanation=`Chaque étape du brouillon est plafonnée à ${amount} €.`;}
 else return {ok:false,error:'Simulation locale : essayez « ajouter une validation humaine », « délai de 48 heures », « renforcer les preuves » ou « budget de 25 € ». Aucune IA n’a interprété cette demande.'};
 return {...result,explanation:`${explanation} Modification déterministe locale, à relire avant publication.`};}
export function applyImprovement(id,improvementId){const p=currentProcess(id);const proposal=p?.improvements.find(i=>i.id===improvementId);if(!proposal)return fail('Proposition introuvable.');if(proposal.applied)return fail('Cette proposition figure déjà dans le brouillon.');const result=editDraft(id,d=>{if(improvementId==='parallel')d.nodes.filter(n=>n.stageId==='draft').forEach(n=>n.estimatedMinutes=Math.max(1,Math.round(n.estimatedMinutes*.8)));if(improvementId==='evidence')d.nodes.forEach(n=>n.evidence='Source, extrait de preuve et critères d’acceptation explicitement documentés.');if(improvementId==='staffing')d.nodes.filter(n=>n.kind==='agent').forEach(n=>n.staffing='best');},'Amélioration appliquée au brouillon');if(result.ok)update(s=>findProcess(s,id).improvements.find(i=>i.id===improvementId).applied=true,'Proposition retenue',proposal.title);return result;}
